476	static int sf32lb52_bt_recv_cb(uint8_t *data, uint16_t len)
477	{
478	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
479	  ssize_t packet_len;
480	  int ret;
481	
482	  if (data == NULL || len == 0)
483	    {
484	      return -EINVAL;
485	    }
486	
487	
488	  if (priv->drop_rx_until_tx)
489	    {
490	      return OK;
491	    }
492	
493	  if (priv->rxlen + len > sizeof(priv->rxbuf))
494	    {
495	      syslog(LOG_ERR,
496	             "sf32lb52 bth4 rx overflow: pending=%lu incoming=%u\n",
497	             (unsigned long)priv->rxlen,
498	             len);
499	      priv->rxlen = 0;
500	    }
501	
502	  memcpy(&priv->rxbuf[priv->rxlen], data, len);
503	  priv->rxlen += len;
504	
505	#if SF32LB52_BT_TRACE
506	  syslog(LOG_INFO,
507	         "sf32lb52 bth4 recv: len=%u pending=%lu first=%02x\n",
508	         len, (unsigned long)priv->rxlen, priv->rxbuf[0]);
509	#endif
510	
511	  ret = OK;
512	
513	  while (priv->rxlen > 0)
514	    {
515	      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
516	      if (packet_len == 0)
517	        {
518	          break;
519	        }
520	
521	      if (packet_len < 0)
522	        {
523	          syslog(LOG_WARNING,
524	                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
525	                 priv->rxbuf[0],
526	                 (unsigned long)priv->rxlen);
527	          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
528	          priv->rxlen--;
529	          ret = -EINVAL;
530	          continue;
531	        }
532	
533	      if ((size_t)packet_len > priv->rxlen)
534	        {
535	          break;
536	        }
537	
538	      ret = sf32lb52_bt_forward_packet(priv, priv->rxbuf,
539	                   (size_t)packet_len);
540	
541	      priv->rxlen -= (size_t)packet_len;
542	      if (priv->rxlen > 0)
543	        {
544	          memmove(priv->rxbuf,
545	                  &priv->rxbuf[packet_len],
546	                  priv->rxlen);
547	        }
548	    }
549	
550	  return ret;
551	}
