553	static int sf32lb52_bt_send(struct bt_driver_s *drv,
554	                            enum bt_buf_type_e type,
555	                            void *data, size_t len)
556	{
557	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
558	  uint8_t *hdr = (uint8_t *)data - drv->head_reserve;
559	  uint16_t opcode;
560	  int ret;
561	
562	
563	  switch (type)
564	    {
565	      case BT_CMD:
566	        *hdr = H4_CMD;
