578	  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
579	    {
580	      opcode = sf32lb52_bt_get_le16(data);
581	      if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
