601	  priv->drop_rx_until_tx = false;
602	
603	  if (SF32LB52_BT_TRACE && type == BT_ACL_OUT)
604	    {
605	      syslog(LOG_INFO,
606	             "sf32lb52 bth4 tx: type=%u len=%lu h4=%02x acl=%02x %02x %02x %02x\n",
607	             (unsigned int)type,
608	             (unsigned long)(len + drv->head_reserve),
609	             hdr[0],
