4206	void hci_event_prio(struct bt_dev *hdev, struct net_buf *buf)
4207	{
4208		struct net_buf_simple_state state;
4209		struct bt_hci_evt_hdr *hdr;
4210		uint8_t evt_flags;
4211	
4212		net_buf_simple_save(&buf->b, &state);
4213	
4214		if (buf->len < sizeof(*hdr)) {
4215			LOG_ERR("Invalid HCI event size (%u)", buf->len);
4216			net_buf_unref(buf);
4217			return;
4218		}
4219	
4220		hdr = net_buf_pull_mem(buf, sizeof(*hdr));
4221		evt_flags = bt_hci_evt_get_flags(hdr->evt);
4222		BT_ASSERT(evt_flags & BT_HCI_EVT_FLAG_RECV_PRIO);
4223	
4224		handle_event(hdev, hdr->evt, buf, prio_events, ARRAY_SIZE(prio_events));
4225	
4226		if (evt_flags & BT_HCI_EVT_FLAG_RECV) {
4227			net_buf_simple_restore(&buf->b, &state);
4228		} else {
4229			net_buf_unref(buf);
4230		}
4231	}
