4233	static void rx_queue_put(struct bt_dev *hdev, struct net_buf *buf)
4234	{
4235		net_buf_slist_put(&hdev->rx_queue, buf);
4236	
4237	#if defined(CONFIG_BT_RECV_WORKQ_SYS)
4238		const int err = k_work_submit(&hdev->rx_work);
4239	#elif defined(CONFIG_BT_RECV_WORKQ_BT)
4240		const int err = k_work_submit_to_queue(&bt_workq, &hdev->rx_work);
4241	#endif /* CONFIG_BT_RECV_WORKQ_SYS */
4242		if (err < 0) {
4243			LOG_ERR("Could not submit rx_work: %d", err);
4244		}
4245	}
